// Till audio cues (doc §1.9), bundled locally and generated by scripts/gen-audio.mjs.
import approval from "@/assets/audio/approval.wav";
import complete from "@/assets/audio/complete.wav";
import error from "@/assets/audio/error.wav";
import tick from "@/assets/audio/tick.wav";
import warning from "@/assets/audio/warning.wav";

export const CUES = { tick, error, approval, complete, warning } as const;
export type Cue = keyof typeof CUES;

interface Playable {
  volume: number;
  play: () => Promise<void>;
}

let prefs = { volume: 0.8, muted: false };

/** Volume 0–1 and mute come from device settings. */
export function setAudioPrefs(next: { volume?: number; muted?: boolean }) {
  prefs = {
    volume: Math.max(0, Math.min(1, next.volume ?? prefs.volume)),
    muted: next.muted ?? prefs.muted,
  };
}

/** Fire-and-forget: audio must never block or fail a sale. */
export function playCue(cue: Cue, create: (src: string) => Playable = (src) => new Audio(src)): void {
  if (prefs.muted) return;
  try {
    const audio = create(CUES[cue]);
    audio.volume = prefs.volume;
    // Some engines return undefined instead of a promise, or reject when playback is refused.
    void Promise.resolve(audio.play()).catch(() => undefined);
  } catch {
    // Audio unavailable (no output device, unsupported engine): the cue is optional feedback.
  }
}
